import React, { useState, useEffect } from 'react';
import { documentService } from '../../services/documentService';
import { clientService } from '../../services/clientService';
import { useAuth } from '../../contexts/AuthContext';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import {
  Folder,
  FolderPlus,
  Upload,
  Search,
  ChevronRight,
  Home,
  Calendar,
  Download,
  Trash2,
  MoreVertical,
} from 'lucide-react';
import Swal from 'sweetalert2';

export const DocumentManager = () => {
  const { user } = useAuth();
  const [clients, setClients] = useState([]);
  const [selectedClient, setSelectedClient] = useState(null);
  const [folders, setFolders] = useState([]);
  const [documents, setDocuments] = useState([]);
  const [currentPath, setCurrentPath] = useState([]);
  const [currentFolderId, setCurrentFolderId] = useState(null);
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadClients();
  }, []);

  useEffect(() => {
    if (selectedClient) {
      loadFolders();
      loadDocuments();
    }
  }, [selectedClient, currentFolderId, selectedYear, selectedMonth, searchTerm]);

  const loadClients = async () => {
    try {
      const data = await clientService.getAll();
      setClients(data);
      if (data.length > 0) {
        setSelectedClient(data[0]._id);
      }
    } catch (error) {
      Swal.fire('Error', 'Error al cargar clientes', 'error');
    }
  };

  const loadFolders = async () => {
    try {
      const data = await documentService.getFolders(selectedClient, currentFolderId);
      setFolders(data);
    } catch (error) {
      console.error('Error loading folders:', error);
    }
  };

  const loadDocuments = async () => {
    try {
      setLoading(true);
      const data = await documentService.getAll({
        client_id: selectedClient,
        folder_id: currentFolderId,
        year: selectedYear,
        month: selectedMonth,
        search: searchTerm,
      });
      setDocuments(data);
    } catch (error) {
      console.error('Error loading documents:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateFolder = async () => {
    const { value: folderName } = await Swal.fire({
      title: 'Nueva Carpeta',
      input: 'text',
      inputLabel: 'Nombre de la carpeta',
      inputPlaceholder: 'Ej: Auditorías 2025',
      showCancelButton: true,
      confirmButtonColor: '#16a34a',
      inputValidator: (value) => {
        if (!value) return 'El nombre es requerido';
      },
    });

    if (folderName) {
      try {
        await documentService.createFolder({
          name: folderName,
          client_id: selectedClient,
          parent_folder_id: currentFolderId,
        });
        loadFolders();
        Swal.fire('Éxito', 'Carpeta creada', 'success');
      } catch (error) {
        Swal.fire('Error', 'Error al crear carpeta', 'error');
      }
    }
  };

  const handleNavigateFolder = (folder) => {
    setCurrentFolderId(folder._id);
    setCurrentPath([...currentPath, folder]);
  };

  const handleBreadcrumb = (index) => {
    if (index === -1) {
      setCurrentFolderId(null);
      setCurrentPath([]);
    } else {
      setCurrentFolderId(currentPath[index]._id);
      setCurrentPath(currentPath.slice(0, index + 1));
    }
  };

  const handleDeleteDocument = async (docId) => {
    const result = await Swal.fire({
      title: '¿Eliminar documento?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      confirmButtonText: 'Sí, eliminar',
    });

    if (result.isConfirmed) {
      try {
        await documentService.delete(docId);
        loadDocuments();
        Swal.fire('Éxito', 'Documento eliminado', 'success');
      } catch (error) {
        Swal.fire('Error', 'Error al eliminar', 'error');
      }
    }
  };

  const months = [
    'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
    'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre',
  ];

  const years = Array.from({ length: 10 }, (_, i) => new Date().getFullYear() - i);

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Gestor de Documentos</h1>
          <p className="text-gray-600">Organiza tus documentos por carpetas, cliente, año y mes</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          {/* Sidebar - Selección de Cliente */}
          <div className="lg:col-span-1">
            <Card>
              <CardHeader>
                <CardTitle className="text-lg">Clientes</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {clients.map((client) => (
                    <button
                      key={client._id}
                      onClick={() => {
                        setSelectedClient(client._id);
                        setCurrentFolderId(null);
                        setCurrentPath([]);
                      }}
                      className={`w-full text-left px-4 py-2 rounded-lg transition-all ${
                        selectedClient === client._id
                          ? 'bg-green-100 text-green-700 border border-green-300'
                          : 'hover:bg-gray-100 text-gray-700'
                      }`}
                    >
                      <div className="font-semibold text-sm truncate">
                        {client.company_name}
                      </div>
                    </button>
                  ))}
                </div>
              </CardContent>
            </Card>

            {/* Filtros */}
            <Card className="mt-4">
              <CardHeader>
                <CardTitle className="text-lg">Filtros</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    <Calendar className="w-4 h-4 inline mr-2" />
                    Año
                  </label>
                  <select
                    value={selectedYear}
                    onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                    className="w-full px-3 py-2 border rounded-lg"
                  >
                    {years.map((year) => (
                      <option key={year} value={year}>
                        {year}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Mes
                  </label>
                  <select
                    value={selectedMonth}
                    onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
                    className="w-full px-3 py-2 border rounded-lg"
                  >
                    {months.map((month, index) => (
                      <option key={index} value={index + 1}>
                        {month}
                      </option>
                    ))}
                  </select>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Main Content */}
          <div className="lg:col-span-3">
            {/* Acciones */}
            <div className="flex flex-col sm:flex-row gap-3 mb-6">
              <div className="flex-1 relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  placeholder="Buscar documentos..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10"
                />
              </div>
              <Button
                onClick={handleCreateFolder}
                className="bg-blue-600 hover:bg-blue-700"
              >
                <FolderPlus className="w-4 h-4 mr-2" />
                Nueva Carpeta
              </Button>
              <Button className="bg-green-600 hover:bg-green-700">
                <Upload className="w-4 h-4 mr-2" />
                Subir Documento
              </Button>
            </div>

            {/* Breadcrumb */}
            {currentPath.length > 0 && (
              <div className="mb-4 p-3 bg-white rounded-lg border flex items-center gap-2 overflow-x-auto">
                <button
                  onClick={() => handleBreadcrumb(-1)}
                  className="flex items-center gap-1 text-green-600 hover:underline whitespace-nowrap"
                >
                  <Home className="w-4 h-4" />
                  Inicio
                </button>
                {currentPath.map((folder, index) => (
                  <React.Fragment key={folder._id}>
                    <ChevronRight className="w-4 h-4 text-gray-400 flex-shrink-0" />
                    <button
                      onClick={() => handleBreadcrumb(index)}
                      className="text-green-600 hover:underline whitespace-nowrap"
                    >
                      {folder.name}
                    </button>
                  </React.Fragment>
                ))}
              </div>
            )}

            {/* Carpetas */}
            {folders.length > 0 && (
              <div className="mb-6">
                <h3 className="font-semibold text-gray-900 mb-3">Carpetas</h3>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                  {folders.map((folder) => (
                    <div
                      key={folder._id}
                      onClick={() => handleNavigateFolder(folder)}
                      className="p-4 bg-white rounded-lg border border-gray-200 hover:border-blue-500 cursor-pointer transition-all"
                    >
                      <Folder className="w-8 h-8 text-blue-500 mb-2" />
                      <p className="text-sm font-medium text-gray-900 truncate">
                        {folder.name}
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Documentos */}
            <div>
              <h3 className="font-semibold text-gray-900 mb-3">Documentos</h3>
              {loading ? (
                <div className="text-center py-8">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-green-500 mx-auto"></div>
                </div>
              ) : documents.length > 0 ? (
                <div className="space-y-2">
                  {documents.map((doc) => (
                    <div
                      key={doc._id}
                      className="p-4 bg-white rounded-lg border hover:border-green-500 transition-all flex items-center justify-between"
                    >
                      <div className="flex-1 min-w-0">
                        <p className="font-medium text-gray-900 truncate">{doc.title}</p>
                        <p className="text-sm text-gray-500">
                          {doc.file_name} · {(doc.file_size / 1024 / 1024).toFixed(2)} MB
                        </p>
                      </div>
                      <div className="flex gap-2 ml-4">
                        <button className="p-2 hover:bg-gray-100 rounded">
                          <Download className="w-4 h-4 text-gray-600" />
                        </button>
                        <button
                          onClick={() => handleDeleteDocument(doc._id)}
                          className="p-2 hover:bg-red-50 rounded"
                        >
                          <Trash2 className="w-4 h-4 text-red-600" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 bg-white rounded-lg border border-dashed">
                  <p className="text-gray-500">No hay documentos en esta carpeta</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DocumentManager;
